'use strict';

// Image3 模型目录：只允许两个模型 ID，禁止旧别名，声明各自能力。

const { MODELS } = require('@aigc-desk/contracts');

const IMAGE3_MODELS = Object.freeze([MODELS.IMAGE_3, MODELS.IMAGE_3_PRO]);

const CATALOG = Object.freeze({
  [MODELS.IMAGE_3]: Object.freeze({
    type: 'image',
    maxReferenceImages: 3,
    supportsAgent: false
  }),
  [MODELS.IMAGE_3_PRO]: Object.freeze({
    type: 'image',
    maxReferenceImages: 3,
    supportsAgent: false
  })
});

function isImage3Model(model) {
  return typeof model === 'string' && Object.prototype.hasOwnProperty.call(CATALOG, model);
}

function getImage3Catalog(model) {
  if (!isImage3Model(model)) {
    const err = new Error(`未知 Image3 模型：${model}`);
    err.code = 'IMAGE3_MODEL_INVALID';
    err.status = 400;
    throw err;
  }
  return CATALOG[model];
}

module.exports = { IMAGE3_MODELS, CATALOG, isImage3Model, getImage3Catalog };
